import{_ as e,c as r,o as s,ae as o}from"./chunks/framework.CHDT0Kbg.js";const p=JSON.parse('{"title":"Qué es Persim","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/introduction.md","filePath":"es/guide/introduction.md","lastUpdated":1795170900000}'),i={name:"es/guide/introduction.md"};function t(l,a,n,d,u,c){return s(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="que-es-persim" tabindex="-1">Qué es Persim <a class="header-anchor" href="#que-es-persim" aria-label="Permalink to &quot;Qué es Persim&quot;">​</a></h1><p>Un navegador para Mac listo desde el primer momento: pestañas, búsqueda, marcadores y descargas.</p><h2 id="desde-el-primer-clic" tabindex="-1">Desde el primer clic <a class="header-anchor" href="#desde-el-primer-clic" aria-label="Permalink to &quot;Desde el primer clic&quot;">​</a></h2><ul><li><strong>Navegar y buscar.</strong> Escribe una dirección o una pregunta en la barra. Los sitios que más visitas aparecen primero.</li><li><strong>Pestañas y ventanas.</strong> Abre, arrastra, agrupa, silencia y previsualiza. Pulsa ⌘⇧A para encontrar una pestaña.</li><li><strong>Volver a encontrar.</strong> Marcadores, barra de marcadores, historial, descargas y «Restaurar la última sesión».</li></ul><h2 id="un-poco-mas-tranquilo" tabindex="-1">Un poco más tranquilo <a class="header-anchor" href="#un-poco-mas-tranquilo" aria-label="Permalink to &quot;Un poco más tranquilo&quot;">​</a></h2><ul><li>Bloqueo de anuncios con suscripciones, reglas propias y lista de permitidos.</li><li>Fuerza el modo oscuro en páginas, silencia pestañas y bloquea ventanas emergentes desde Ajustes.</li><li>Una ventana privada (⌘⇧N) no guarda el historial.</li></ul><h2 id="videos-y-textos-largos" tabindex="-1">Vídeos y textos largos <a class="header-anchor" href="#videos-y-textos-largos" aria-label="Permalink to &quot;Vídeos y textos largos&quot;">​</a></h2><ul><li>El panel multimedia muestra los vídeos de la página; al guardarlos obtienes un MP4 que puedes abrir con la app que quieras.</li><li>El modo lectura (⌘⇧R) conserva el artículo y quita el ruido. Puedes capturar lo que ves o la página completa en PDF.</li></ul><h2 id="a-tu-manera" tabindex="-1">A tu manera <a class="header-anchor" href="#a-tu-manera" aria-label="Permalink to &quot;A tu manera&quot;">​</a></h2><p>Claro, oscuro o según el sistema; seis colores de acento; tres modos de barra de marcadores; 25 idiomas. El aspecto cambia al instante; el idioma se aplica al volver a abrir la ventana.</p>',10)])])}const h=e(i,[["render",t]]);export{p as __pageData,h as default};
